-- A222-02.bemessung_methodik
update public.fields set verification_status='verified_against_standard', verification_quote='Zur Überprüfung der Messwerte oder wenn keine Messwerte über Menge und Beschaffenheit des zu behandelnden Abwassers vorliegen, kann bei Kläranlagen ab 50 E der Einwohnerwert aus der Zahl der im anzuschließenden Gebiet vorhandenen Einwohner, gegebenenfalls vorhandenem gewerblichem Abwasseranfall sowie der prognostischen Entwicklung ermittelt werden. | Kläranlagen bis 50 E sollten grundsätzlich auf die maximale Belegung bzw. Nutzung einer Wohnsiedlung und einzelner Gebäude sowie sonstiger baulicher Anlagen bemessen werden. Die für die Bemessung maßgebliche Einwohnerzahl richtet sich nach der Anzahl der darin wohnenden oder voraussichtlich unterzubringenden Einwohner. — printed p.11', verification_note='md-verified 2026-09-05 (§3.2, printed p.11) [VC]', verified_at=now() where id='601b1739-4029-4050-8568-1012fb9332fc' and verification_status not in ('verified_against_standard','corrected');
-- A222-02.system_typ
update public.fields set verification_status='verified_against_standard', verification_quote='Das Arbeitsblatt gilt auch für Kläranlagen mit Anschlusswerten unter 50 E, wo mit Fremdwasseranfall gerechnet werden muss. Es gilt nicht für Kleinkläranlagen, denen im Definitionssinn kein Fremdwasser zufließen darf. | Im oberen Geltungsbereich können in Ausnahmefällen bei bestehenden Mischwasserkanalnetzen bei Beachtung der hydraulischen Randbedingungen Anlagen nach diesem Arbeitsblatt bemessen werden. — printed p.6', verification_note='md-verified 2026-09-05 (§1, printed p.6) [VC]', verified_at=now() where id='317c5016-ded6-4f23-9d0c-daf656f43d8e' and verification_status not in ('verified_against_standard','corrected');
