-- A222-04.A_TK_spez
update public.fields set verification_status='verified_against_standard', verification_quote='Diese Werte basieren auf einer spezifischen Oberfläche $A_{\text {TK,spez }}=100 \mathrm{~m}^{2} / \mathrm{m}^{3}$ und sind auch anzusetzen, wenn Material mit größerer spezifischer Oberfläche eingesetzt wird. | Für Tropfkörpermaterial gilt DIN 19557. Die spezifische Oberfläche der Füllelemente muss sein: $90 \mathrm{~m}^{2} / \mathrm{m}^{3} \leq A_{\mathrm{TK}, \text { spez }} \leq 150 \mathrm{~m}^{2} / \mathrm{m}^{3}$. Bereits bei Füllelementen mit $A_{\mathrm{TK}, \mathrm{spez}}$ ab $150 \mathrm{~m}^{2} / \mathrm{m}^{3}$ können Verstopfungen auftreten. — printed p.13 / p.22', verification_note='md-verified 2026-09-05 (§4.3.2, §5.3, printed p.13 / p.22) [VC]', verified_at=now() where id='40f4f2ec-9c08-4b7b-9dc2-5a218bc49f27' and verification_status not in ('verified_against_standard','corrected');
-- A222-04.V_TK
update public.fields set verification_status='verified_against_standard', verification_quote='Das erforderliche Tropfkörpervolumen wird nach Gleichung (8) errechnet: $$ \begin{equation*} V_{\mathrm{TK}}=\frac{E W \times V_{\mathrm{TK}, \mathrm{EWspez}}}{1.000}\left(\mathrm{~m}^{3}\right) \tag{8} — printed p.13', verification_note='md-verified 2026-09-05 (§4.3.2 Gl. (8), printed p.13) [VC]', verified_at=now() where id='83ce36b4-a936-43eb-9263-fca4da1d6247' and verification_status not in ('verified_against_standard','corrected');
-- A222-04.A_TK
update public.fields set verification_status='verified_against_standard', verification_quote='Die erforderliche Grundfläche $A_{\mathrm{TK}}$ des Tropfkörpers wird nach Gleichung (9) errechnet: $$ \begin{equation*} A_{\mathrm{TK}}=\frac{V_{\mathrm{TK}}}{h_{\mathrm{TK}}} \quad\left(\mathrm{~m}^{2}\right) \tag{9} — printed p.13', verification_note='md-verified 2026-09-05 (§4.3.2 Gl. (9), printed p.13) [VC] — CAVEAT: the md calls A_TK the "erforderliche Grundfläche" of the trickling filter, while §2.2 lists A_TK as "theoretische Oberfläche des Tropfkörpers" — the encoded label follows §2.2', verified_at=now() where id='6e624c5d-0fa9-4102-b1ae-37e9fcc1f68a' and verification_status not in ('verified_against_standard','corrected');
-- A222-04.q_A_TK
update public.fields set verification_status='verified_against_standard', verification_quote='Zu Spülzwecken muss eine Flächenbeschickung $q_{\text {A,TK }}$ von mindestens $1,6 \mathrm{~m}^{3} /\left(\mathrm{m}^{2} \cdot \mathrm{~h}\right)$ bei Tropfkörpern mit Kunst-stoff-Füllmaterial bzw. $0,8 \mathrm{~m}^{3} /\left(\mathrm{m}^{2} \cdot \mathrm{~h}\right)$ bei brockengefüllten Tropfkörpern sichergestellt werden. — printed p.13', verification_note='md-verified 2026-09-05 (§4.3.2, printed p.13) [VC]', verified_at=now() where id='00c38c4a-79b9-4d48-ab98-0b46980339f6' and verification_status not in ('verified_against_standard','corrected');
-- A222-06.n_RT
update public.fields set verification_status='verified_against_standard', verification_quote='Die erforderliche theoretische Oberfläche muss auf mindestens zwei hintereinander durchflossene Rotationstauchkörper aufgeteilt werden. Der Abstand der Scheiben muss mindestens 18 mm betragen (siehe Bild 1). Ist eine gesicherte Nitrifikation erforderlich, muss die erforderliche theoretische Oberfläche auf mindestens drei hintereinander durchflossene Rotationstauchkörper aufgeteilt werden. Dann kann der Abstand der Scheiben beim zweiten und den weiteren Rotationstauchkörpern auf mindestens 15 mm reduziert werden. — printed p.14', verification_note='md-verified 2026-09-05 (§4.3.3, printed p.14) [VC]', verified_at=now() where id='49393426-5f0e-44ce-8998-79aab01e6052' and verification_status not in ('verified_against_standard','corrected');
