-- A222-07.Q_L
update public.fields set verification_status='verified_against_standard', verification_quote='Der für die Durchmischung und die Begrenzung der Biofilmdicke erforderliche Luftvolumenstrom $Q_{\mathrm{L}}$ kann mit folgender Gleichung ermittelt werden: $$ \begin{equation*} Q_{\mathrm{L}}=u_{\mathrm{L}} \times A_{\mathrm{R}, \mathrm{FB}}\left(\mathrm{Nm}^{3} / \mathrm{h}\right) \tag{12} \end{equation*} $$ mit Leerrohrgeschwindigkeit $5 \mathrm{~m} / \mathrm{h} \leq u_{\mathrm{L}} \leq 10 \mathrm{~m} / \mathrm{h}$. — printed p.15', verification_note='md-verified 2026-09-05 (§4.3.4 Gl. (12), printed p.15) [VC]', verified_at=now() where id='4e78f863-acc6-4959-9b3a-c71c6b0a533e' and verification_status not in ('verified_against_standard','corrected');
-- A222-07.A_FB_spez
update public.fields set verification_status='verified_against_standard', verification_quote='Diese Werte basieren auf einer spezifischen Oberfläche $A_{\mathrm{FB}, \text { spez }}=100 \mathrm{~m}^{2} / \mathrm{m}^{3}$ und sind grundsätzlich auch anzusetzen, wenn Material mit größerer spezifischer Oberfläche eingesetzt wird. In der zweiten und den nachfolgenden Kammern der Kaskade kann bei Einsatz von Material mit einer größeren spezifischen Oberfläche mit dieser gerechnet werden, maximal aber mit $\leq 150 \mathrm{~m}^{2} / \mathrm{m}^{3}$. — printed p.14–15', verification_note='md-verified 2026-09-05 (§4.3.4, Tabelle 4 Anmerkung 1), printed p.14–15) [VC]', verified_at=now() where id='743cbff1-82ab-4183-9c90-1372b5318213' and verification_status not in ('verified_against_standard','corrected');
