update public.fields set verification_status='verified_against_standard', verification_quote='Die Luftmengen müssen in einem ausreichend weiten Bereich $(1: 10)$ variierbar sein, um die Erfordernisse, die sich aus Belüftung, Durchmischung und Feststoffaustrag ergeben, abdecken zu können. — printed p.22–23', verification_note='md-verified 2026-09-05 (§5.5, printed p.22–23) [VC]', verified_at=now() where id='0c084e8b-9ad4-4f4b-a9c9-ebf160cac8bc' and verification_status not in ('verified_against_standard','corrected');
-- A222-07.V_FB_50E
update public.fields set verification_status='verified_against_standard', verification_quote='Für Kläranlagen unter 50 E müssen die spezifischen Werte $V_{\mathrm{FB}, \mathrm{EWspez}}$ in Tabelle 4 Spalte 2 um jeweils $5 \%$ (des Ausgangswerts) je 4 E Unterschreitung erhöht werden. [...] damit ein erforderliches spezifisches Volumen $V_{\mathrm{FB}, \mathrm{EW} \text { spez }}=68 \mathrm{l} / \mathrm{E} \times 1,40=95,2 \mathrm{l} / \mathrm{E}$. — printed p.14–15', verification_note='md-verified 2026-09-05 (§4.3.4, printed p.14–15) [VC]', verified_at=now() where id='acdcfc43-6202-4dad-aaf4-f5f2608a61ee' and verification_status not in ('verified_against_standard','corrected');
-- A222-07.n_FB_Kaskaden
update public.fields set verification_status='verified_against_standard', verification_quote='Das erforderliche Festbettvolumen muss bei Anlagen > 50 E auf mindestens zwei hintereinander durchflossene Kaskaden aufgeteilt werden. Ist eine gesicherte Nitrifikation erforderlich, muss die erforderliche theoretische Oberfläche auf mindestens drei hintereinander durchflossene Kaskaden aufgeteilt werden. Alternativ ist eine Gestaltung als Becken mit Pfropfenströmung möglich. — printed p.15', verification_note='md-verified 2026-09-05 (§4.3.4, printed p.15) [VC]', verified_at=now() where id='528d1d40-36e0-437d-a4db-2171826f6f1f' and verification_status not in ('verified_against_standard','corrected');
-- A222-08.V_SB
update public.fields set verification_status='verified_against_standard', verification_quote='Damit wird das erforderliche Aufwuchskörpervolumen aus der spezifischen wirksamen Aufwuchsfläche der gewählten Aufwuchskörper $A_{\mathrm{SB}, \mathrm{spez}}$ errechnet zu: $$ \begin{equation*} V_{\mathrm{SB}}=\frac{A_{\mathrm{SB}}}{A_{\mathrm{SB}, \mathrm{spez}}}\left(\mathrm{~m}^{3}\right) \tag{14} — printed p.15', verification_note='md-verified 2026-09-05 (§4.3.5 Gl. (14), printed p.15) [VC]', verified_at=now() where id='8d3267a4-1aea-49ae-a79a-e5ae394435cc' and verification_status not in ('verified_against_standard','corrected');
-- A222-08.A_SB_EWspez
update public.fields set verification_status='verified_against_standard', verification_quote='Es liegen zurzeit keine verallgemeinerungsfähigen Bemessungswerte für Anlagen mit frei beweglichen Aufwuchskörpern vor. Daher sind die folgenden Bemessungsvorgaben nur als Anhaltswerte zu verstehen (siehe Tabelle 5). | \caption{Tabelle 5: Interpolationsbereich für die spezifische Oberfläche der frei beweglichen Aufwuchskörper (bezogen auf E im Rohabwasser) (nur Anhaltswerte, daher eingeklammert)} \begin{tabular}{|l|l|l|} \hline \multirow{2}{*}{} & \multicolumn{2}{|c|}{$A_{\text {SB,EWspez }}$ ( $\mathrm{m}^{2} / \mathrm{E}$ )} \\ \hline & $\leq 50 \mathrm{E}$ & 1.000 E \\ \hline Mindestanforderungen & (20) & (10) \\ \hline mit Nitrifikation & (40) & (20) \\ \hline \end{tabular} — printed p.15', verification_note='md-verified 2026-09-05 (§4.3.5, Tabelle 5, printed p.15) [VC]', verified_at=now() where id='3e869db4-9532-4614-a3db-609d27d134b9' and verification_status not in ('verified_against_standard','corrected');
