update public.fields set verification_status='verified_against_standard', verification_quote='Kurzzeichen & Einheit & Erläuterung | \hline $t_{F}$ & h & Dauer der Füllphase \\ | Im unteren Geltungsbereich muss im Zulauf ein Speichervolumen mit einem Mindestvolumen nach Gleichung 16 bereitgestellt werden. Speichervolumen: $$ \begin{equation*} V_{\mathrm{Sp}}=\int_{0}^{\mathrm{t}} Q_{\mathrm{bem}} \mathrm{dt} \text { und } \leq Q_{\mathrm{d}}\left(\mathrm{~m}^{3}\right) \tag{16} \end{equation*} $$ $$ \text { (mit } t=\frac{t_{\mathrm{z}}}{n}-t_{\mathrm{F}} \text { ) } — printed p.7–9 / p.16', verification_note='md-verified 2026-09-05 (§2.2, §4.3.6 Gl. (16), printed p.7–9 / p.16) [VC]', verified_at=now() where id='8283ef2c-a1f4-4b9a-b814-a79edf23127f' and verification_status not in ('verified_against_standard','corrected');
