-- A222-09.t_z
update public.fields set verification_status='verified_against_standard', verification_quote='Kurzzeichen & Einheit & Erläuterung | \hline $t_{\mathrm{z}}$ & h & Zyklusdauer \\ | Im Folgenden sind auf der Basis dieser Berechnungsmethode bei Verwendung der angegebenen Standardvorgaben ( $m$ je nach Ausbaugröße, $t_{\mathrm{z}}=8 \mathrm{~h}$ ) die resultierenden SBR-Volumina angegeben. Die angegebenen Bemessungsvorgaben beziehen sich ausschließlich auf Anlagen im Trennsystem, Anlagen mit Mischwasserzulauf sind gegebenenfalls nach Merkblatt DWA-M 210 zu bemessen. — printed p.7–9 / p.16', verification_note='md-verified 2026-09-05 (§2.2, §4.3.6, printed p.7–9 / p.16) [VC]', verified_at=now() where id='e345be90-9852-41dd-8764-8b97c4bcc4ec' and verification_status not in ('verified_against_standard','corrected');
