-- A222-09.t_Ab
update public.fields set verification_status='verified_against_standard', verification_quote='Im oberen Geltungsbereich sollte die Abzugsphase $t_{\mathrm{Ab}}$ 0,5 bis 1 Stunde bei $Q_{\text {bem }}$ betragen. Im unteren Geltungsbereich wird die Dauer der Abzugsphase primär durch die Leistungsfähigkeit der eingesetzten Abzugsaggregate bestimmt. Der Abzugsvolumenstrom muss (in Abhängigkeit von der Abzugseinrichtung) so niedrig gewählt werden, dass es nicht zu Schlammaustrag kommen kann. — printed p.16', verification_note='md-verified 2026-09-05 (§4.3.6, printed p.16) [VC]', verified_at=now() where id='b62e05bf-cd3c-4888-967c-08fa96865b87' and verification_status not in ('verified_against_standard','corrected');
