-- A222-10.C_O
update public.fields set verification_status='verified_against_standard', verification_quote='Die Belüftungseinrichtungen müssen so gestaltet und ausgelegt werden, dass intermittierender Betrieb möglich ist. Der Sauerstoffgehalt im Belebungsbecken $C_{\mathrm{O}}$ sollte in der belüfteten Phase mindestens $2 \mathrm{mg} / \mathrm{l}$ erreichen können. — printed p.18', verification_note='md-verified 2026-09-05 (§4.3.7, printed p.18) [VC]', verified_at=now() where id='63278592-14b5-4afc-8fa7-3818e609094d' and verification_status not in ('verified_against_standard','corrected');
-- A222-10.alpha
update public.fields set verification_status='verified_against_standard', verification_quote='Wird das Sauerstoffzufuhrvermögen in Reinwasser unter Standardbedingungen angegeben, so muss dieses um den Faktor 1/α größer sein als das berechnete erforderliche Sauerstoffzufuhrvermögen in belebtem Schlamm. Der Sauerstoffzufuhrfaktor $\alpha$ ist bei Druckluft- und Oberflächenbelüftungssystemen unterschiedlich. Für Oberflächenbelüftungssysteme wird der $\alpha$-Wert üblicherweise um 0,9 angesetzt. Bei der Druckluftbelüftung können $\alpha$-Werte von 0,6 bis 0,7 angesetzt werden. In der Praxis haben sich folgende Bemessungsangaben für den Sauerstoffertrag bzw. -eintrag in belebtem Schlamm bewährt, von denen nur in besonderen Fällen abgewichen werden sollte: — printed p.18', verification_note='md-verified 2026-09-05 (§4.3.7, printed p.18) [VC]', verified_at=now() where id='f3093a2e-b9e4-4e9f-b676-d630d6232655' and verification_status not in ('verified_against_standard','corrected');
-- A222-10.h_E
update public.fields set verification_status='verified_against_standard', verification_quote='Kurzzeichen & Einheit & Erläuterung | \hline $h_{\mathrm{E}}$ & m & Einblastiefe \\ | Der Luftvolumenstrom zur Abdeckung der erforderlichen Sauerstoffzufuhr in belebtem Schlamm ( $\alpha O C$ ) wird in Abhängigkeit von der Einblastiefe $h_{\mathrm{E}}$ nach Gleichung (21) errechnet: $$ \begin{equation*} Q_{\mathrm{L}, \mathrm{St}}=\frac{\alpha \mathrm{OC}}{\alpha \mathrm{OC}_{\mathrm{L}, \mathrm{~h}} \times h_{\mathrm{E}}} \times \frac{t_{\mathrm{T}}}{t_{\mathrm{N}}}\left(\mathrm{~m}^{3} / \mathrm{h}\right) \tag{21} — printed p.7–9 / p.18', verification_note='md-verified 2026-09-05 (§2.2, §4.3.7 Gl. (21), printed p.7–9 / p.18) [VC]', verified_at=now() where id='53ba945e-d6a6-42f2-8b38-8cad9687ff1b' and verification_status not in ('verified_against_standard','corrected');
