-- A222-10.Q_L_St
update public.fields set verification_status='verified_against_standard', verification_quote='Der Luftvolumenstrom zur Abdeckung der erforderlichen Sauerstoffzufuhr in belebtem Schlamm ( $\alpha O C$ ) wird in Abhängigkeit von der Einblastiefe $h_{\mathrm{E}}$ nach Gleichung (21) errechnet: $$ \begin{equation*} Q_{\mathrm{L}, \mathrm{St}}=\frac{\alpha \mathrm{OC}}{\alpha \mathrm{OC}_{\mathrm{L}, \mathrm{~h}} \times h_{\mathrm{E}}} \times \frac{t_{\mathrm{T}}}{t_{\mathrm{N}}}\left(\mathrm{~m}^{3} / \mathrm{h}\right) \tag{21} — printed p.18', verification_note='md-verified 2026-09-05 (§4.3.7 Gl. (21), printed p.18) [VC]', verified_at=now() where id='fd91f40f-1737-41ea-b74c-bb031f696849' and verification_status not in ('verified_against_standard','corrected');
-- A222-10.V_BB_EWspez
update public.fields set verification_status='verified_against_standard', verification_quote='\caption{Tabelle 7: Interpolationsbereich für das spezifische Belebungsbeckenvolumen (bezogen auf E im Rohabwasser)} \begin{tabular}{|l|l|l|} \hline & Häusliches Schmutzwasser & Schmutzwasser mit nennenswertem gewerblichen Anteil \\ \hline ISV $\quad(\mathrm{ml} / \mathrm{g})$ & 100 & 150 \\ \hline $T S_{\text {BB }} \quad\left(\mathrm{kg} / \mathrm{m}^{3}\right)$ & $\leq 4,9$ & $\leq 3,3$ \\ \hline $V_{\mathrm{BB}, \mathrm{EW} \text { spez }}$ (l/EW) & $\geq 245$ & $\geq 370$ \\ \hline \end{tabular} — printed p.18', verification_note='md-verified 2026-09-05 (§4.3.7, Tabelle 7, printed p.18) [VC]', verified_at=now() where id='d7fa7fe0-4363-40c9-9977-894ac39bcdfa' and verification_status not in ('verified_against_standard','corrected');
-- A222-10.ISV
update public.fields set verification_status='verified_against_standard', verification_quote='Kurzzeichen & Einheit & Erläuterung | \hline ISV & $\mathrm{ml} / \mathrm{g}$ & Schlammindex \\ | \caption{Tabelle 7: Interpolationsbereich für das spezifische Belebungsbeckenvolumen (bezogen auf E im Rohabwasser)} \begin{tabular}{|l|l|l|} \hline & Häusliches Schmutzwasser & Schmutzwasser mit nennenswertem gewerblichen Anteil \\ \hline ISV $\quad(\mathrm{ml} / \mathrm{g})$ & 100 & 150 \\ \hline $T S_{\text {BB }} \quad\left(\mathrm{kg} / \mathrm{m}^{3}\right)$ & $\leq 4,9$ & $\leq 3,3$ \\ \hline $V_{\mathrm{BB}, \mathrm{EW} \text { spez }}$ (l/EW) & $\geq 245$ & $\geq 370$ \\ \hline \end{tabular} — printed p.7–9 / p.18', verification_note='md-verified 2026-09-05 (§2.2, §4.3.7 Tabelle 7, printed p.7–9 / p.18) [VC]', verified_at=now() where id='708253f0-c134-4da2-bb4b-748bc459472a' and verification_status not in ('verified_against_standard','corrected');
-- A222-10.t_TS
update public.fields set verification_status='verified_against_standard', verification_quote='Das erforderliche Belebungsbeckenvolumen wird bei einem Bemessungsschlammalter von 25 Tagen, bei betrieblicher Denitrifikation und Verwendung der Standardvorgaben nach Gleichung (17) errechnet: $$ \begin{equation*} V_{\mathrm{BB}}=\frac{E W \times V_{\mathrm{BB}, \mathrm{EW} \text { spez }}}{1.000}\left(\mathrm{~m}^{3}\right) \tag{17} — printed p.18', verification_note='md-verified 2026-09-05 (§4.3.7 Gl. (17), printed p.18) [VC] — CAVEAT: the standard fixes the design sludge age at 25 d for Gl. (17); it is a fixed design premise, not a free input', verified_at=now() where id='2b9c4867-4723-4c3c-a812-bfd49bd1d72f' and verification_status not in ('verified_against_standard','corrected');
-- A222-10.OC
update public.fields set verification_status='verified_against_standard', verification_quote='Aus betrieblichen Gründen ist die gezielte Denitrifikation empfehlenswert. Die erforderliche Sauerstoffzufuhr unter Betriebsbedingungen ergibt sich dann unter Berücksichtigung der belüftungsfreien Zeiten bei intermittierender Denitrifikation zu: $$ \begin{equation*} \alpha O C=0,1 \times B_{\mathrm{d}, \mathrm{BSB}, \mathrm{ZB}} \times \frac{1}{1-t_{\mathrm{D}} /\left(t_{\mathrm{D}}+t_{\mathrm{N}}\right)} \quad(\mathrm{kg} / \mathrm{h}) \tag{19} — printed p.18', verification_note='md-verified 2026-09-05 (§4.3.7 Gl. (19), printed p.18) [VC] — CAVEAT: the md names this quantity αOC in Gl. (18) AND Gl. (19); the encoding carries it twice (aOC + OC) — duplicate flagged in the STAGED file', verified_at=now() where id='3407a28d-f613-4523-b6ba-0391af9fc3c6' and verification_status not in ('verified_against_standard','corrected');
-- A222-10.P_spez
update public.fields set verification_status='verified_against_standard', verification_quote='In jedem Fall muss zur Verhinderung von Schlammsedimentation eine ausreichende Fließgeschwindigkeit und Durchmischung sichergestellt sein. Hierzu ist eine Leistungsdichte der Umwälzeinrichtungen bei getrennter Umwälzung, bezogen auf das Beckenvolumen von rd. $1 \mathrm{~W} / \mathrm{m}^{3}$ bis $5 \mathrm{~W} / \mathrm{m}^{3}$ notwendig. Der tatsächliche Praxiswert ist neben der Beckenform und -größe auch von den Schlammabsetzeigenschaften (ISV) und vom Schlammgehalt ( $T S_{\mathrm{BB}}$ ) abhängig. — printed p.18–19', verification_note='md-verified 2026-09-05 (§4.3.7, printed p.18–19) [VC]', verified_at=now() where id='ac935800-4276-4a08-bc22-244761283c53' and verification_status not in ('verified_against_standard','corrected');
-- A222-12.t_T
update public.fields set verification_status='verified_against_standard', verification_quote='Die Taktdauer $t_{\mathrm{T}}$ ergibt sich zu: $$ \begin{equation*} t_{\mathrm{T}}=t_{\mathrm{D}}+t_{\mathrm{N}}(\mathrm{~h}) \tag{20} — printed p.18', verification_note='md-verified 2026-09-05 (§4.3.7 Gl. (20), printed p.18) [VC]', verified_at=now() where id='0c451cfb-b64c-4a6b-9651-70ec8e5fa8fe' and verification_status not in ('verified_against_standard','corrected');
