-- A222-12.t_D
update public.fields set verification_status='verified_against_standard', verification_quote='Dabei sollte der Quotient $$ \frac{t_{\mathrm{D}}}{t_{\mathrm{T}}} \leq 0,35 $$ sein, um eine ausreichende Schlammstabilisierung zu gewährleisten und die Gefahr einer Blähschlammbildung zu vermindern. — printed p.18', verification_note='md-verified 2026-09-05 (§4.3.7, printed p.18) [VC]', verified_at=now() where id='6fa8de32-a3d8-475d-a369-61638ba5a47a' and verification_status not in ('verified_against_standard','corrected');
-- A222-12.denitrifikation
update public.fields set verification_status='verified_against_standard', verification_quote='Aus betrieblichen Gründen ist die gezielte Denitrifikation empfehlenswert. Die erforderliche Sauerstoffzufuhr unter Betriebsbedingungen ergibt sich dann unter Berücksichtigung der belüftungsfreien Zeiten bei intermittierender Denitrifikation zu: $$ \begin{equation*} \alpha O C=0,1 \times B_{\mathrm{d}, \mathrm{BSB}, \mathrm{ZB}} \times \frac{1}{1-t_{\mathrm{D}} /\left(t_{\mathrm{D}}+t_{\mathrm{N}}\right)} \quad(\mathrm{kg} / \mathrm{h}) \tag{19} — printed p.18', verification_note='md-verified 2026-09-05 (§4.3.7, printed p.18) [VC]', verified_at=now() where id='71bba488-82ef-4608-987d-125f84e6c7e5' and verification_status not in ('verified_against_standard','corrected');
-- A222-12.t_N_relativ
update public.fields set verification_status='verified_against_standard', verification_quote='Für die Auslegung der Belüftung wird empfohlen, eine Belüftungszeit $\mathrm{t}_{\mathrm{N}}$ /belüftetes Volumen von maximal $65 \%$ anzusetzen, um auch bei höheren Temperaturen eine ausreichende Sauerstoffversorgung zu gewährleisten, wenn der belüftete Anteil reduziert wird. Damit ist der Normallastfall 80 \% belüfteter Anteil sicher abgedeckt. — printed p.18', verification_note='md-verified 2026-09-05 (§4.3.7, printed p.18) [VC]', verified_at=now() where id='c91f0e6b-1e55-4132-a6fc-701d1af77654' and verification_status not in ('verified_against_standard','corrected');
