-- A222-16.V_speicher_EWspez
update public.fields set verification_status='verified_against_standard', verification_quote='Das erforderliche Speichervolumen richtet sich nach den Entsorgungsmöglichkeiten, muss aber mindestens 100 1/E betragen. Der Schlammstapelraum kann als getrennter Behälter bereitgestellt oder z. B. in einem Emscherbrunnen mit der Vorklärung kombiniert werden. | Im unteren Geltungsbereich sollten Vorklärung und Schlammspeicherung in einem gemeinsamen Behälter erfolgen. Dieser muss ein Mindestvolumen von $\geq 375$ 1/E einschließlich Vorklärung aufweisen. Das entspricht einer Speicherzeit von bis zu 3 Monaten bei Vollauslastung. — printed p.21', verification_note='md-verified 2026-09-05 (§4.5, printed p.21) [VC]', verified_at=now() where id='c8e7d4ef-17e2-4a5d-82c5-ea198b7a54c8' and verification_status not in ('verified_against_standard','corrected');
-- A222-16.V_VK_speicher_EWspez
update public.fields set verification_status='verified_against_standard', verification_quote='Im unteren Geltungsbereich sollten Vorklärung und Schlammspeicherung in einem gemeinsamen Behälter erfolgen. Dieser muss ein Mindestvolumen von $\geq 375$ 1/E einschließlich Vorklärung aufweisen. Das entspricht einer Speicherzeit von bis zu 3 Monaten bei Vollauslastung. — printed p.21', verification_note='md-verified 2026-09-05 (§4.5, printed p.21) [VC]', verified_at=now() where id='e66396f9-6e00-4287-9890-c0677ef8addc' and verification_status not in ('verified_against_standard','corrected');
-- A222-16.ue_schlamm_spez
update public.fields set verification_status='verified_against_standard', verification_quote='Die tägliche Überschussschlammproduktion kann im Falle fehlender Messwerte für Tropfkörper, Rotationstauchkörper, Festbettanlagen und Anlagen mit frei beweglichen Aufwuchskörpern mit $0,03 \mathrm{~kg}$ TS pro angeschlossenem Einwohnerwert und Tag, für Belebungsanlagen mit gemeinsamer aerober Stabilisierung, SBR und Kombinationsanlagen mit $0,06 \mathrm{~kg}$ TS pro angeschlossenem Einwohnerwert und Tag angenommen werden. — printed p.21', verification_note='md-verified 2026-09-05 (§4.5, printed p.21) [VC]', verified_at=now() where id='d4f9f184-2c03-42b3-bdbf-1773ab0024e0' and verification_status not in ('verified_against_standard','corrected');
