-- A222-24.mindestanforderungen_abwv_anh1
update public.fields set verification_status='verified_against_standard', verification_quote='Für die in diesem Arbeitsblatt behandelten Kläranlagen gelten in der Regel die Mindestanforderungen nach Anhang 1 der Abwasserverordnung ( AbwV ) für die Größenklasse 1. Darauf stellen die Bemessungsvorgaben ab. | Mit den nach diesem Arbeitsblatt bemessenen Anlagen kann über die Reinigungsanforderungen der Größenklasse 1 nach AbwV hinaus ein weitgehend ammoniumfreier Ablauf erreicht werden. Voraussetzung hierfür ist, dass ausreichend befähigtes und fachlich ausgebildetes Betriebspersonal eingesetzt wird. — printed p.13 / p.26', verification_note='md-verified 2026-09-05 (§4.3.1, §8, printed p.13 / p.26) [VC]', verified_at=now() where id='47359f2b-17bb-4162-a943-a4ede89637f6' and verification_status not in ('verified_against_standard','corrected');
