-- A222-24.betriebsanweisung_dwa_a_199_4
update public.fields set verification_status='verified_against_standard', verification_quote='Für eine Kläranlage muss eine umfassende, allgemeinverständliche Betriebsanweisung in Anlehnung an das Arbeitsblatt DWA-A 199-4 - die insbesondere auf die verfahrens- und ortsspezifischen Besonderheiten eingeht - für alle in der Praxis auftretenden Betriebszustände erstellt und dem Anlagenbetreiber ausgehändigt werden. — printed p.24', verification_note='md-verified 2026-09-05 (§6.1, printed p.24) [VC]', verified_at=now() where id='b3089cba-d7b7-4f96-a191-15c8a11409cf' and verification_status not in ('verified_against_standard','corrected');

