update public.equations set verification_status='verified_against_standard', verification_quote='Sind Anlagen im oberen Geltungsbereich im Ausnahmefall hinter einem Mischsystem angeordnet, ergibt sich der bemessungsrelevante maximale Volumenstrom zu: $$ \begin{equation*} Q_{\mathrm{bem}}=f_{\mathrm{S}, \mathrm{QM}} \times Q_{\mathrm{S}, \mathrm{aM}}+Q_{\mathrm{F}} \quad(1 / \mathrm{s}) \tag{4} | Für $f_{\mathrm{S}, \mathrm{QM}}$ sollten Werte zwischen 6 und 9 gewählt werden (nach Arbeitsblatt ATV-DVWK-A 198). — printed p.10–11', verification_note='md-verified 2026-09-05 (§3.1 Gl. (4), printed p.10–11) [VC]', verified_at=now() where id='c037b88b-7fda-4b9a-82d1-909b5003b925' and verification_status <> 'verified_against_standard';
