update public.equations set verification_status='verified_against_standard', verification_quote='Liegen verwertbare Zulauffrachtdaten im Sinne des Arbeitsblattes ATV-DVWK-A 198 vor, kann der für die Bemessung relevante Einwohnerwert nach folgender Gleichung aus der $\mathrm{BSB}_{5}$ - oder CSB-Tagesfracht (siehe Tabelle 1) ermittelt werden: | E W_{\mathrm{xxx}}=\frac{B_{\mathrm{d}, \mathrm{xxx}, \mathrm{ZB}}}{b_{\mathrm{xxx}, 85}} \times 1000(\mathrm{E}) \tag{7} — printed p.11', verification_note='md-verified 2026-09-05 (§3.2 Gl. (7), printed p.11) [VC]', verified_at=now() where id='04272fe1-637f-490e-ac47-aac2f59ec9ac' and verification_status <> 'verified_against_standard';
