update public.equations set verification_status='verified_against_standard', verification_quote='Das erforderliche Tropfkörpervolumen wird nach Gleichung (8) errechnet: $$ \begin{equation*} V_{\mathrm{TK}}=\frac{E W \times V_{\mathrm{TK}, \mathrm{EWspez}}}{1.000}\left(\mathrm{~m}^{3}\right) \tag{8} — printed p.13', verification_note='md-verified 2026-09-05 (§4.3.2 Gl. (8), printed p.13) [VC]', verified_at=now() where id='dfa314fa-cfca-4f3c-a589-571c77c91f4f' and verification_status <> 'verified_against_standard';
-- Gl.9
update public.equations set verification_status='verified_against_standard', verification_quote='Die erforderliche Grundfläche $A_{\mathrm{TK}}$ des Tropfkörpers wird nach Gleichung (9) errechnet: $$ \begin{equation*} A_{\mathrm{TK}}=\frac{V_{\mathrm{TK}}}{h_{\mathrm{TK}}} \quad\left(\mathrm{~m}^{2}\right) \tag{9} — printed p.13', verification_note='md-verified 2026-09-05 (§4.3.2 Gl. (9), printed p.13) [VC]', verified_at=now() where id='6853b5b0-57fb-4e96-8ed8-ceabb548e292' and verification_status <> 'verified_against_standard';
-- Gl.10
update public.equations set verification_status='verified_against_standard', verification_quote='Die erforderliche theoretische Rotationstauchkörperoberfläche wird nach Gleichung (10) errechnet: $$ \begin{equation*} A_{\mathrm{RT}}=\mathrm{EW} \times A_{\mathrm{RT}, \mathrm{EW} \text { spez }}\left(\mathrm{m}^{2}\right) \tag{10} — printed p.14', verification_note='md-verified 2026-09-05 (§4.3.3 Gl. (10), printed p.14) [VC]', verified_at=now() where id='61f69df6-fc97-4f24-a600-91c86d0dabaa' and verification_status <> 'verified_against_standard';
-- Gl.11
update public.equations set verification_status='verified_against_standard', verification_quote='Das erforderliche Festbettvolumen wird nach Gleichung (11) errechnet: $$ \begin{equation*} V_{\mathrm{FB}}=\frac{E W \times V_{\mathrm{FB}, \text { EWspez }}}{1.000} \quad\left[\mathrm{~m}^{3}\right] \tag{11} — printed p.14', verification_note='md-verified 2026-09-05 (§4.3.4 Gl. (11), printed p.14) [VC]', verified_at=now() where id='5c50ea53-b261-49f9-ba5d-0bbbd900a3f8' and verification_status <> 'verified_against_standard';
-- Gl.12
update public.equations set verification_status='verified_against_standard', verification_quote='Der für die Durchmischung und die Begrenzung der Biofilmdicke erforderliche Luftvolumenstrom $Q_{\mathrm{L}}$ kann mit folgender Gleichung ermittelt werden: $$ \begin{equation*} Q_{\mathrm{L}}=u_{\mathrm{L}} \times A_{\mathrm{R}, \mathrm{FB}}\left(\mathrm{Nm}^{3} / \mathrm{h}\right) \tag{12} \end{equation*} $$ mit Leerrohrgeschwindigkeit $5 \mathrm{~m} / \mathrm{h} \leq u_{\mathrm{L}} \leq 10 \mathrm{~m} / \mathrm{h}$. — printed p.15', verification_note='md-verified 2026-09-05 (§4.3.4 Gl. (12), printed p.15) [VC]', verified_at=now() where id='b6ba221c-727b-4930-8901-617ce9c32675' and verification_status <> 'verified_against_standard';
-- Gl.13
update public.equations set verification_status='verified_against_standard', verification_quote='Die erforderliche Oberfläche der Aufwuchskörper wird nach Gleichung (13) errechnet: $$ \begin{equation*} A_{\mathrm{SB}}=E W \times A_{\mathrm{SB}, \mathrm{EWspez}}\left(\mathrm{~m}^{2}\right) \tag{13} — printed p.15', verification_note='md-verified 2026-09-05 (§4.3.5 Gl. (13), printed p.15) [VC]', verified_at=now() where id='3664b6b9-2aba-46d5-9913-bc96ad291641' and verification_status <> 'verified_against_standard';
-- Gl.14
update public.equations set verification_status='verified_against_standard', verification_quote='Damit wird das erforderliche Aufwuchskörpervolumen aus der spezifischen wirksamen Aufwuchsfläche der gewählten Aufwuchskörper $A_{\mathrm{SB}, \mathrm{spez}}$ errechnet zu: $$ \begin{equation*} V_{\mathrm{SB}}=\frac{A_{\mathrm{SB}}}{A_{\mathrm{SB}, \mathrm{spez}}}\left(\mathrm{~m}^{3}\right) \tag{14} — printed p.15', verification_note='md-verified 2026-09-05 (§4.3.5 Gl. (14), printed p.15) [VC]', verified_at=now() where id='ff161561-c998-4479-a2f1-246bbedbd619' and verification_status <> 'verified_against_standard';
