update public.equations set verification_status='verified_against_standard', verification_quote='Im unteren Geltungsbereich muss im Zulauf ein Speichervolumen mit einem Mindestvolumen nach Gleichung 16 bereitgestellt werden. Speichervolumen: $$ \begin{equation*} V_{\mathrm{Sp}}=\int_{0}^{\mathrm{t}} Q_{\mathrm{bem}} \mathrm{dt} \text { und } \leq Q_{\mathrm{d}}\left(\mathrm{~m}^{3}\right) \tag{16} \end{equation*} $$ $$ \text { (mit } t=\frac{t_{\mathrm{z}}}{n}-t_{\mathrm{F}} \text { ) } — printed p.16', verification_note='md-verified 2026-09-05 (§4.3.6 Gl. (16), printed p.16) [VC]', verified_at=now() where id='06083afc-159c-4306-8e0f-4d7701ac1597' and verification_status <> 'verified_against_standard';
-- Gl.17
update public.equations set verification_status='verified_against_standard', verification_quote='Das erforderliche Belebungsbeckenvolumen wird bei einem Bemessungsschlammalter von 25 Tagen, bei betrieblicher Denitrifikation und Verwendung der Standardvorgaben nach Gleichung (17) errechnet: $$ \begin{equation*} V_{\mathrm{BB}}=\frac{E W \times V_{\mathrm{BB}, \mathrm{EW} \text { spez }}}{1.000}\left(\mathrm{~m}^{3}\right) \tag{17} — printed p.18', verification_note='md-verified 2026-09-05 (§4.3.7 Gl. (17), printed p.18) [VC]', verified_at=now() where id='7c3940fe-dd07-4d17-991f-c611be1f593a' and verification_status <> 'verified_against_standard';
-- Gl.18
update public.equations set verification_status='verified_against_standard', verification_quote='Das erforderliche Sauerstoffzufuhrvermögen in Bezug auf Reinwasser ergibt sich zu: $$ \begin{equation*} \alpha O C=0,1 \times B_{\mathrm{d}, \mathrm{BSB}, \mathrm{ZB}} \quad(\mathrm{~kg} / \mathrm{h}) \tag{18} — printed p.18', verification_note='md-verified 2026-09-05 (§4.3.7 Gl. (18), printed p.18) [VC]', verified_at=now() where id='c6fe6294-9e4e-46e9-8e5d-479199a4a911' and verification_status <> 'verified_against_standard';
-- Gl.19
update public.equations set verification_status='verified_against_standard', verification_quote='Aus betrieblichen Gründen ist die gezielte Denitrifikation empfehlenswert. Die erforderliche Sauerstoffzufuhr unter Betriebsbedingungen ergibt sich dann unter Berücksichtigung der belüftungsfreien Zeiten bei intermittierender Denitrifikation zu: $$ \begin{equation*} \alpha O C=0,1 \times B_{\mathrm{d}, \mathrm{BSB}, \mathrm{ZB}} \times \frac{1}{1-t_{\mathrm{D}} /\left(t_{\mathrm{D}}+t_{\mathrm{N}}\right)} \quad(\mathrm{kg} / \mathrm{h}) \tag{19} — printed p.18', verification_note='md-verified 2026-09-05 (§4.3.7 Gl. (19), printed p.18) [VC]', verified_at=now() where id='34b01c3c-a779-4c31-9794-07ab4df8bd88' and verification_status <> 'verified_against_standard';
-- Gl.20
update public.equations set verification_status='verified_against_standard', verification_quote='Die Taktdauer $t_{\mathrm{T}}$ ergibt sich zu: $$ \begin{equation*} t_{\mathrm{T}}=t_{\mathrm{D}}+t_{\mathrm{N}}(\mathrm{~h}) \tag{20} — printed p.18', verification_note='md-verified 2026-09-05 (§4.3.7 Gl. (20), printed p.18) [VC]', verified_at=now() where id='89c5e51b-9c99-404a-8310-4266129ae1b8' and verification_status <> 'verified_against_standard';
-- Gl.21
update public.equations set verification_status='verified_against_standard', verification_quote='Der Luftvolumenstrom zur Abdeckung der erforderlichen Sauerstoffzufuhr in belebtem Schlamm ( $\alpha O C$ ) wird in Abhängigkeit von der Einblastiefe $h_{\mathrm{E}}$ nach Gleichung (21) errechnet: $$ \begin{equation*} Q_{\mathrm{L}, \mathrm{St}}=\frac{\alpha \mathrm{OC}}{\alpha \mathrm{OC}_{\mathrm{L}, \mathrm{~h}} \times h_{\mathrm{E}}} \times \frac{t_{\mathrm{T}}}{t_{\mathrm{N}}}\left(\mathrm{~m}^{3} / \mathrm{h}\right) \tag{21} — printed p.18', verification_note='md-verified 2026-09-05 (§4.3.7 Gl. (21), printed p.18) [VC]', verified_at=now() where id='58d13766-5b65-431a-b15b-dfb7763b86fa' and verification_status <> 'verified_against_standard';
-- Gl.22
update public.equations set verification_status='verified_against_standard', verification_quote='Für die Berechnung ist die theoretische Oberfläche maßgebend. Sie ergibt sich zu: $$ \begin{equation*} A_{\mathrm{NB}, \text { theo }} \geq \frac{Q_{\mathrm{bem}} \times(1+R V)}{2,2}\left(\mathrm{~m}^{2}\right) \tag{22} — printed p.19', verification_note='md-verified 2026-09-05 (§4.4.2 Gl. (22), printed p.19) [VC]', verified_at=now() where id='f5215c5e-172a-4151-8288-b4342bb9b4ca' and verification_status <> 'verified_against_standard';
-- Gl.23
update public.equations set verification_status='verified_against_standard', verification_quote='Die erforderlichen Beckentiefen betragen: bis $100 \mathrm{E} \quad h_{\mathrm{z}}=0 \mathrm{~m}$ über $100 \mathrm{E} \quad h_{\mathrm{z}} \leq 0,5 \mathrm{~m}$ $h_{\text {ges }}=\sqrt[3]{A_{\mathrm{NB}, \text { theo }} \times 18}(\mathrm{~m})$ nicht dimensionsecht $$ \begin{equation*} h_{\mathrm{t}}=h_{\text {ges }}-\mathrm{h}_{\mathrm{z}} \quad(\mathrm{m}) \tag{24} \end{equation*} $$ $$ \begin{equation*} h_{\mathrm{e}} \cong h_{\text {ges }} \times 0,3 \quad(\mathrm{~m}) \tag{25} — printed p.19–20', verification_note='md-verified 2026-09-05 (§4.4.2 Gl. (23), printed p.19–20) [VC]', verified_at=now() where id='cb95fa54-cd46-430c-a947-ff9d5ab64ea9' and verification_status <> 'verified_against_standard';
-- Gl.24
