update public.equations set verification_status='verified_against_standard', verification_quote='Die erforderlichen Beckentiefen betragen: bis $100 \mathrm{E} \quad h_{\mathrm{z}}=0 \mathrm{~m}$ über $100 \mathrm{E} \quad h_{\mathrm{z}} \leq 0,5 \mathrm{~m}$ $h_{\text {ges }}=\sqrt[3]{A_{\mathrm{NB}, \text { theo }} \times 18}(\mathrm{~m})$ nicht dimensionsecht $$ \begin{equation*} h_{\mathrm{t}}=h_{\text {ges }}-\mathrm{h}_{\mathrm{z}} \quad(\mathrm{m}) \tag{24} \end{equation*} $$ $$ \begin{equation*} h_{\mathrm{e}} \cong h_{\text {ges }} \times 0,3 \quad(\mathrm{~m}) \tag{25} — printed p.19–20', verification_note='md-verified 2026-09-05 (§4.4.2 Gl. (25), printed p.19–20) [VC]', verified_at=now() where id='0acb45c4-7b0f-4249-b298-da25d823a992' and verification_status <> 'verified_against_standard';
