update public.equations set verification_status='verified_against_standard', verification_quote='Der erforderliche Radius $r_{\mathrm{NB}}$ des Trichterbeckens wird nach Gleichung (26) ermittelt: $$ \begin{equation*} r_{\mathrm{NB}}=\frac{h_{\text {ges }}-h_{z}}{1,7}(\mathrm{~m}) \tag{26} — printed p.20', verification_note='md-verified 2026-09-05 (§4.4.2 Gl. (26), printed p.20) [VC]', verified_at=now() where id='3d839ee0-7832-4556-8dee-808382d3fe03' and verification_status <> 'verified_against_standard';
-- Gl.27
update public.equations set verification_status='verified_against_standard', verification_quote='Bis 100 E und generell bei Tropfkörpern, Rotationstauchkörpern und Festbettanlagen können auch horizontal durchströmte Nachklärbecken mit den nachstehenden Bemessungsvorgaben eingesetzt werden. $$ \begin{equation*} A_{\mathrm{NB}} \geq \frac{Q_{\mathrm{bem}} \times(1+R V)}{2,8}\left(\mathrm{~m}^{2}\right) \tag{27} — printed p.20', verification_note='md-verified 2026-09-05 (§4.4.3 Gl. (27), printed p.20) [VC]', verified_at=now() where id='285e3568-0773-4177-821c-9bf2ea769553' and verification_status <> 'verified_against_standard';
-- Gl.28
update public.equations set verification_status='verified_against_standard', verification_quote='Die Durchflusszeit $t_{\mathrm{NB}}$ muss im unteren Geltungsbereich bis 50 E mindestens 3,5 Stunden, im oberen Geltungsbereich mindestens 2,5 Stunden betragen. Dann wird das erforderliche Nachklärvolumen nach Gleichung (28) errechnet: $$ \begin{equation*} V_{\mathrm{NB}}=Q_{\mathrm{bem}} \times(1+R V) \times t_{\mathrm{NB}}\left(\mathrm{~m}^{3}\right) \tag{28} — printed p.20', verification_note='md-verified 2026-09-05 (§4.4.3 Gl. (28), printed p.20) [VC]', verified_at=now() where id='2a3b9364-e945-4bbf-aac5-a8fb1305e8ec' and verification_status <> 'verified_against_standard';
